 	exclude_GH_default = true;
 	perf_host  = 0;
@@ -2155,34 +2156,37 @@ int cmd_kvm(int argc, const char **argv)
 	if (!perf_host)
 		perf_guest = 1;
 
-	if (!file_name) {
+	if (!file_name)
 		file_name = get_filename_for_perf_kvm();
 
